package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.JsonNode;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.entitlement.*;
import org.junit.jupiter.api.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.jdbc.core.JdbcTemplate;
import java.time.*;import java.sql.Timestamp;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.MOCK,properties={"app.commerce.fake.auto-success=false","app.commerce.expiration-scan-ms=3600000"})
class CatalogReportingBoundaryTest extends CatalogPaymentStateTest {
 @MockBean Clock reportingClock;
 final Instant fixed=Instant.parse("2026-10-03T12:00:00Z");
 static JdbcTemplate lastJdbc;
 @BeforeEach void fixedReportingClock(){when(reportingClock.instant()).thenReturn(fixed);when(reportingClock.getZone()).thenReturn(ZoneOffset.UTC);when(reportingClock.withZone(any())).thenReturn(reportingClock);lastJdbc=jdbc;}
 @AfterAll static void cleaned(){for(String table:List.of("commerce_orders","commerce_payment_attempts","commerce_payment_events","product_entitlements","users","roles"))assertEquals(0L,lastJdbc.queryForObject("select count(*) from "+table,Long.class));Map<String,Object> o=new LinkedHashMap<>();o.put("case_id","CLEANUP");o.put("label","all-local-fixtures-removed");o.put("tables_empty",true);o.put("no_listening_http_server",true);observations.add(o);}
 Product course(User who,String price){Product p=seed(ProductType.COURSE,who,price,ProductStatus.PUBLISHED);readyArticle(p);return p;}
 UUID made(String label,User creator,User customer,String state)throws Exception{Product p=course(creator,"12.25");UUID id=orderId(checkout("SETUP",label,customer,List.of(p.getId()),label,201));if(!state.equals("PENDING"))simulate("SETUP",id,state,200);return id;}
 JsonNode read(String c,String label,String path,User who,int status)throws Exception{var request=get(path);if(who!=null)request.cookie(auth(who));JsonNode n=perform(c,label,request,status);if(status!=200){assertFalse(n.toString().contains("buyer@example.com"));assertFalse(n.toString().contains("creator@example.com"));}return n;}
 Set<String> contentIds(JsonNode page){Set<String> ids=new HashSet<>();for(JsonNode x:page.path("content"))ids.add(x.path("id").asText());return ids;}
 String reportMetric(JsonNode report,String label){for(JsonNode x:report.path("metrics"))if(x.path("label").asText().equals(label))return x.path("value").asText();throw new AssertionError(label+" missing");}
 @Test void sales010Validation()throws Exception{
  UUID id=made("validation",owner,buyer,"PAID");
  for(String q:List.of("period=invalid","period=30D","status=invalid","status=expired","sort=invalid","page=-1","page=not-int","pageSize=0","pageSize=101","pageSize=not-int","product=not-uuid"))read("SALES-010",q,"/api/creator/orders?"+q,owner,400);
  read("SALES-010","malformed-order","/api/creator/orders/not-uuid",owner,400);
  read("SALES-010","missing-order","/api/creator/orders/"+UUID.randomUUID(),owner,404);
  for(String value:List.of("invalid","30D","week"))read("SALES-010","summary-"+value,"/api/creator/sales/summary?period="+value,owner,400);
  for(String value:List.of("today","7d","30d","90d"))assertEquals(value,read("SALES-010","period-"+value,"/api/creator/sales/summary?period="+value,owner,200).path("period").asText());
  for(int size:List.of(1,6,100)){var n=read("SALES-010","pageSize-"+size,"/api/creator/orders?pageSize="+size,owner,200);assertEquals(size,n.path("size").asInt());assertEquals(Set.of(id.toString()),contentIds(n));}
  var past=read("SALES-010","past-last-page","/api/creator/orders?page=99&pageSize=1",owner,200);assertEquals(0,past.path("content").size());assertEquals(1,past.path("totalElements").asInt());assertEquals(1,orders.count());assertEquals(1,grants.count());
 }
 @Test void sales011Isolation()throws Exception{
  UUID a=made("creator-a",owner,buyer,"PAID");User b=extra("reporting-creator-b",owner),bb=extra("reporting-buyer-b",buyer);UUID other=made("creator-b",b,bb,"PAID");
  for(User who:List.of(owner,b)){UUID own=who==owner?a:other,foreign=who==owner?other:a;User foreignCreator=who==owner?b:owner;
   assertEquals(Set.of(own.toString()),contentIds(read("SALES-011","own-ledger","/api/creator/orders",who,200)));
   assertEquals(Set.of(own.toString()),contentIds(read("SALES-011","forged-selector","/api/creator/orders?creatorId="+foreignCreator.getUserId(),who,200)));
   read("SALES-011","foreign-order","/api/creator/orders/"+foreign,who,404);
   assertEquals(read("SALES-011","own-summary","/api/creator/sales/summary",who,200),read("SALES-011","forged-summary","/api/creator/sales/summary?creatorId="+foreignCreator.getUserId(),who,200));
  }assertEquals(2,orders.count());assertEquals(2,grants.count());
 }
 @Test void sales012RoleApi()throws Exception{UUID id=made("role-order",owner,buyer,"PAID");for(User who:Arrays.asList(null,buyer,admin))for(String path:List.of("/api/creator/orders","/api/creator/sales/summary","/api/creator/orders/"+id))read("SALES-012",(who==null?"Guest":who==buyer?"User":"Admin")+path,path,who,who==null?401:403);for(String path:List.of("/api/creator/orders","/api/creator/sales/summary","/api/creator/orders/"+id))read("SALES-012","Creator-control"+path,path,owner,200);assertEquals(1,orders.count());}
 @Test void custom011Validation()throws Exception{
  Product p=course(owner,"0");grant(p,buyer,EntitlementSource.FREE_ENROLLMENT,EntitlementStatus.ACTIVE);
  for(String q:List.of("status=invalid","membership=invalid","sort=invalid","page=-1","page=not-int","pageSize=0","pageSize=101","pageSize=not-int","product=not-uuid"))read("CUSTOM-011",q,"/api/creator/customers?"+q,owner,400);
  read("CUSTOM-011","malformed-customer","/api/creator/customers/not-uuid",owner,400);read("CUSTOM-011","missing-customer","/api/creator/customers/"+UUID.randomUUID(),owner,404);
  for(int size:List.of(1,6,100)){JsonNode n=read("CUSTOM-011","supported-size-"+size,"/api/creator/customers?pageSize="+size,owner,200);assertEquals(size,n.path("size").asInt());assertEquals(Set.of(buyer.getUserId().toString()),contentIds(n));}
  assertEquals(0,read("CUSTOM-011","beyond-last","/api/creator/customers?page=99",owner,200).path("content").size());assertEquals(1,grants.count());assertEquals(0,orders.count());
 }
 @Test void custom012IsolationRoles()throws Exception{
  Product p=course(owner,"0");grant(p,buyer,EntitlementSource.FREE_ENROLLMENT,EntitlementStatus.ACTIVE);User b=extra("crm-creator-b",owner),bb=extra("crm-buyer-b",buyer);Product bp=course(b,"0");grant(bp,bb,EntitlementSource.FREE_ENROLLMENT,EntitlementStatus.ACTIVE);
  for(User who:List.of(owner,b)){User customer=who==owner?buyer:bb,foreignCustomer=who==owner?bb:buyer,foreignCreator=who==owner?b:owner;
   JsonNode normal=read("CUSTOM-012","own-list","/api/creator/customers",who,200);assertEquals(Set.of(customer.getUserId().toString()),contentIds(normal));
   assertEquals(normal,read("CUSTOM-012","forged-list","/api/creator/customers?creatorId="+foreignCreator.getUserId(),who,200));
   assertEquals(customer.getUserId().toString(),read("CUSTOM-012","own-detail","/api/creator/customers/"+customer.getUserId(),who,200).path("id").asText());
   read("CUSTOM-012","foreign-detail","/api/creator/customers/"+foreignCustomer.getUserId(),who,404);
  }
  for(User who:Arrays.asList(null,buyer,admin))for(String path:List.of("/api/creator/customers","/api/creator/customers/"+buyer.getUserId()))read("CUSTOM-012",(who==null?"Guest":who==buyer?"User":"Admin")+path,path,who,who==null?401:403);assertEquals(2,grants.count());
 }
 @Test void analytics008PeriodsRoles()throws Exception{
  for(String p:List.of("today","invalid","30D","week","1d"))read("ANALYTICS-008","invalid-"+p,"/api/creator/analytics/overview?period="+p,owner,400);
  for(String p:List.of("7d","30d","90d")){JsonNode n=read("ANALYTICS-008","valid-"+p,"/api/creator/analytics/overview?period="+p,owner,200);assertEquals(p,n.path("period").asText());assertEquals(0,n.path("customerGrowth").path("summary").path("totalCustomers").asInt());}
  for(User who:Arrays.asList(null,buyer,admin))read("ANALYTICS-008",who==null?"Guest":who==buyer?"User":"Admin","/api/creator/analytics/overview",who,who==null?401:403);assertEquals(0,orders.count());assertEquals(0,grants.count());
 }
 @Test void analytics013DashboardApiScope()throws Exception{
  made("dash-a",owner,buyer,"PAID");User b=extra("dash-creator-b",owner),bb=extra("dash-buyer-b",buyer);Product p=course(b,"99.00");UUID id=orderId(checkout("SETUP","dash-b",bb,List.of(p.getId()),"dash-b",201));simulate("SETUP",id,"PAID",200);
  for(User who:List.of(owner,b)){User foreign=who==owner?b:owner;JsonNode normal=read("ANALYTICS-013","own-dashboard","/api/creator/dashboard/summary",who,200);assertEquals(normal,read("ANALYTICS-013","forged-dashboard","/api/creator/dashboard/summary?creatorId="+foreign.getUserId(),who,200));assertTrue(reportMetric(normal,"Revenue").contains(who==owner?"12.25":"99"));assertEquals("1",reportMetric(normal,"Sales"));assertEquals(1,normal.path("topProducts").size());}
  for(User who:Arrays.asList(null,buyer,admin))read("ANALYTICS-013",who==null?"Guest":who==buyer?"User":"Admin","/api/creator/dashboard/summary",who,who==null?401:403);assertEquals(2,orders.count());
 }
 @Test void sales003ExpirationApi()throws Exception{
  UUID live=made("live",owner,buyer,"PENDING"),overdue=made("overdue",owner,buyer,"PENDING"),expired=made("expired",owner,buyer,"PENDING"),paid=made("paid",owner,buyer,"PAID"),failed=made("failed",owner,buyer,"FAILED"),refunded=made("refunded",owner,buyer,"PAID");simulate("SETUP",refunded,"REFUNDED",200);
  jdbc.update("update commerce_orders set created_at=?,expires_at=? where id=?",Timestamp.from(fixed.minusSeconds(600)),Timestamp.from(fixed.plusSeconds(60)),live);
  jdbc.update("update commerce_orders set created_at=?,expires_at=? where id=?",Timestamp.from(fixed.minusSeconds(600)),Timestamp.from(fixed.minusSeconds(60)),overdue);
  jdbc.update("update commerce_orders set status='EXPIRED',created_at=?,expires_at=? where id=?",Timestamp.from(fixed.minusSeconds(600)),Timestamp.from(fixed.minusSeconds(60)),expired);
  Set<String> visible=Set.of(live.toString(),paid.toString(),failed.toString(),refunded.toString());assertEquals(visible,contentIds(read("SALES-003","visible-state-matrix","/api/creator/orders",owner,200)));
  for(UUID x:List.of(overdue,expired))read("SALES-003","invisible-detail","/api/creator/orders/"+x,owner,404);
  JsonNode pending=read("SALES-003","live-pending-detail","/api/creator/orders/"+live,owner,200);assertEquals("pending",pending.path("status").asText());
  for(UUID x:List.of(paid,failed,refunded))read("SALES-003","terminal-detail","/api/creator/orders/"+x,owner,200);
  JsonNode summary=read("SALES-003","no-false-paid-revenue","/api/creator/sales/summary",owner,200);assertEquals("1",reportMetric(summary,"Orders"));assertTrue(reportMetric(summary,"Revenue").contains("12.25"));assertEquals(6,orders.count());
 }
}

package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.JsonNode;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.entitlement.*;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.entitlement.ProductEntitlement;
import com.myproject.video.video_platform.entity.user.User;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class CatalogPaymentStateTest extends CatalogCheckoutMatrixTest {
 UUID orderId(JsonNode n){return UUID.fromString(n.path("orderId").asText());}
 JsonNode simulate(String c,UUID id,String outcome,int status)throws Exception{return perform(c,"simulate-"+outcome,mutation(post("/api/dev/commerce/orders/"+id+"/simulate"),admin).content(mapper.writeValueAsString(Map.of("outcome",outcome))),status);}
 JsonNode readOrder(String c,UUID id)throws Exception{return perform(c,"buyer-order-read",get("/api/commerce/orders/"+id).cookie(auth(buyer)),200);}
 JsonNode library(String c)throws Exception{return perform(c,"buyer-library",get("/api/entitlements/me").cookie(auth(buyer)),200);}
 Set<UUID> libraryIds(String c)throws Exception{Set<UUID> ids=new HashSet<>();for(JsonNode n:library(c))ids.add(UUID.fromString(n.path("product").path("id").asText()));return ids;}
 ProductEntitlement grant(Product p,User u,EntitlementSource source,EntitlementStatus status){ProductEntitlement e=new ProductEntitlement();e.setUser(u);e.setProductId(p.getId());e.setProductType(p.getType());e.setSource(source);e.setStatus(status);if(status==EntitlementStatus.REVOKED)e.setRevokedAt(Instant.now());return grants.saveAndFlush(e);}
 void access(String c,Product p,boolean expected)throws Exception{assertEquals(expected,perform(c,"access-"+expected,get("/api/entitlements/products/"+p.getId()+"/access").cookie(auth(buyer)),200).path("hasAccess").asBoolean());}
 void content(String c,Product p,boolean expected)throws Exception{JsonNode n=perform(c,"protected-course-content-"+expected,get("/api/products/"+p.getId()).cookie(auth(buyer)),200);assertEquals(expected,n.toString().contains("QA ready article"));}
 String metric(String c,String label)throws Exception{JsonNode n=perform(c,"creator-summary-"+label,get("/api/creator/sales/summary").cookie(auth(owner)),200);for(JsonNode m:n.path("metrics"))if(m.path("label").asText().equals(label))return m.path("value").asText();throw new AssertionError("Expected summary label absent: "+label);}
 JsonNode creatorOrder(String c,UUID id,String state)throws Exception{JsonNode n=perform(c,"creator-order-"+state,get("/api/creator/orders/"+id).cookie(auth(owner)),200);assertEquals(state.toLowerCase(Locale.ROOT),n.path("status").asText());JsonNode page=perform(c,"creator-ledger-"+state,get("/api/creator/orders").param("status",state.toLowerCase(Locale.ROOT)).cookie(auth(owner)),200);assertTrue(java.util.stream.StreamSupport.stream(page.path("content").spliterator(),false).anyMatch(x->x.path("id").asText().equals(id.toString())));return n;}
 void overdue(UUID id){var o=orders.findById(id).orElseThrow();o.setExpiresAt(Instant.now().minusSeconds(120));orders.saveAndFlush(o);}
 @Test void pay013AlreadyEntitledCartAtomicRejection()throws Exception{Product a=paid(),b=paid();grant(a,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);checkout("PAY-013","entitled-plus-unowned",buyer,List.of(a.getId(),b.getId()),"already",409);assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());assertEquals(1,grants.count());assertTrue(grants.findByUserUserIdAndProductId(buyer.getUserId(),b.getId()).isEmpty());}
 @Test void pay016PaidEveryItemAndProtectedAccess()throws Exception{List<Product> ps=List.of(paid(),seed(ProductType.DOWNLOAD,owner,"4.00",ProductStatus.PUBLISHED),seed(ProductType.CONSULTATION,owner,"8.00",ProductStatus.PUBLISHED));readyArticle(ps.get(0));JsonNode pending=checkout("PAY-016","pending-three-types",buyer,ps.stream().map(Product::getId).toList(),"paid",201);UUID id=orderId(pending);assertEquals("PENDING",pending.path("status").asText());assertEquals(0,grants.count());JsonNode paid=simulate("PAY-016",id,"PAID",200);assertEquals("PAID",paid.path("status").asText());assertEquals(paid,readOrder("PAY-016",id));assertEquals("SUCCEEDED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertNotNull(orders.findById(id).orElseThrow().getPaidAt());assertEquals(3,grants.count());for(JsonNode item:paid.path("items")){UUID pid=UUID.fromString(item.path("productId").asText());ProductEntitlement e=grants.findByUserUserIdAndProductId(buyer.getUserId(),pid).orElseThrow();assertEquals(EntitlementStatus.ACTIVE,e.getStatus());assertEquals(EntitlementSource.PURCHASE,e.getSource());assertEquals(UUID.fromString(item.path("id").asText()),e.getPurchaseOrderItemId());assertNull(e.getRevokedAt());}assertEquals(new HashSet<>(ps.stream().map(Product::getId).toList()),libraryIds("PAY-016"));for(Product p:ps)access("PAY-016",p,true);content("PAY-016",ps.get(0),true);assertEquals(pending.path("items"),paid.path("items"));assertEquals(1,events.count());}
 @Test void pay017FailedNoGrantAndCreatorReports()throws Exception{Product p=paid();UUID id=orderId(checkout("PAY-017","pending",buyer,List.of(p.getId()),"failed",201));assertEquals("FAILED",simulate("PAY-017",id,"FAILED",200).path("status").asText());assertEquals("FAILED",readOrder("PAY-017",id).path("status").asText());assertEquals("FAILED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertNotNull(orders.findById(id).orElseThrow().getFailedAt());assertEquals(0,grants.count());assertEquals(0,library("PAY-017").size());access("PAY-017",p,false);JsonNode detail=creatorOrder("PAY-017",id,"FAILED");assertFalse(detail.path("failure").isNull());assertEquals("1",metric("PAY-017","Failed payments"));assertEquals("0",metric("PAY-017","Orders"));}
 @Test void pay018RefundOnlyMatchingPurchaseAndCreatorReports()throws Exception{Product a=paid(),b=paid(),free=seed(ProductType.COURSE,owner,"0",ProductStatus.PUBLISHED),manual=paid(),unrelated=paid();for(Product p:List.of(a,b,free,manual,unrelated))readyArticle(p);perform("PAY-018","free-enroll",mutation(post("/api/entitlements/products/"+free.getId()+"/enroll"),buyer),201);grant(manual,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);UUID otherId=orderId(checkout("PAY-018","unrelated-paid-order",buyer,List.of(unrelated.getId()),"other",201));simulate("PAY-018",otherId,"PAID",200);JsonNode pending=checkout("PAY-018","refund-target",buyer,List.of(a.getId(),b.getId()),"refund",201);UUID id=orderId(pending);simulate("PAY-018",id,"PAID",200);for(Product p:List.of(a,b))content("PAY-018",p,true);JsonNode refunded=simulate("PAY-018",id,"REFUNDED",200);assertEquals("REFUNDED",refunded.path("status").asText());assertEquals(refunded,readOrder("PAY-018",id));assertEquals("REFUNDED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertNotNull(orders.findById(id).orElseThrow().getRefundedAt());assertEquals(pending.path("items"),refunded.path("items"));for(JsonNode item:refunded.path("items")){ProductEntitlement e=grants.findByUserUserIdAndProductId(buyer.getUserId(),UUID.fromString(item.path("productId").asText())).orElseThrow();assertEquals(EntitlementSource.PURCHASE,e.getSource());assertEquals(UUID.fromString(item.path("id").asText()),e.getPurchaseOrderItemId());assertEquals(EntitlementStatus.REVOKED,e.getStatus());assertNotNull(e.getRevokedAt());}assertEquals(5,grants.count());assertEquals(Set.of(free.getId(),manual.getId(),unrelated.getId()),libraryIds("PAY-018"));for(Product p:List.of(a,b)){access("PAY-018",p,false);content("PAY-018",p,false);}for(Product p:List.of(free,manual,unrelated)){assertEquals(EntitlementStatus.ACTIVE,grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow().getStatus());access("PAY-018",p,true);content("PAY-018",p,true);}assertEquals("PAID",readOrder("PAY-018",otherId).path("status").asText());JsonNode detail=creatorOrder("PAY-018",id,"REFUNDED");assertEquals(2450,detail.path("refund").path("amountCents").asLong());assertEquals(2,detail.path("items").size());for(JsonNode item:detail.path("items"))assertEquals("revoked",item.path("access").path("state").asText());assertEquals("1",metric("PAY-018","Orders"));assertTrue(metric("PAY-018","Revenue").contains("12.25"));assertTrue(metric("PAY-018","Refunds").contains("24.50"));}
 @Test void pay019RepeatPaidAndRefundNoDuplicateGrant()throws Exception{Product p=paid();UUID id=orderId(checkout("PAY-019","pending",buyer,List.of(p.getId()),"repeat",201));JsonNode first=simulate("PAY-019",id,"PAID",200);var e=grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow();UUID grantId=e.getId();Instant paidAt=orders.findById(id).orElseThrow().getPaidAt();assertEquals(first,simulate("PAY-019",id,"PAID",200));assertEquals(paidAt,orders.findById(id).orElseThrow().getPaidAt());assertEquals(1,grants.count());assertEquals(grantId,grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow().getId());assertEquals(Set.of(p.getId()),libraryIds("PAY-019"));JsonNode refund=simulate("PAY-019",id,"REFUNDED",200);Instant revoked=grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow().getRevokedAt();assertEquals(refund,simulate("PAY-019",id,"REFUNDED",200));e=grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow();assertEquals(grantId,e.getId());assertEquals(revoked,e.getRevokedAt());assertEquals(EntitlementStatus.REVOKED,e.getStatus());assertEquals(1,grants.count());assertEquals(0,library("PAY-019").size());assertEquals(refund,readOrder("PAY-019",id));assertEquals(4,events.count());}
 @Test void pay020InvalidTransitionMatrixAtomic()throws Exception{for(String start:List.of("PENDING","FAILED","EXPIRED","REFUNDED","PAID")){Product p=paid();UUID id=orderId(checkout("PAY-020","create-for-"+start,buyer,List.of(p.getId()),"invalid-"+start,201));if(start.equals("EXPIRED")){overdue(id);readOrder("PAY-020",id);}else if(start.equals("REFUNDED")){simulate("PAY-020",id,"PAID",200);simulate("PAY-020",id,"REFUNDED",200);}else if(!start.equals("PENDING"))simulate("PAY-020",id,start,200);List<String> targets=switch(start){case "PENDING"->List.of("REFUNDED");case "FAILED"->List.of("PAID","REFUNDED");case "EXPIRED"->List.of("PAID","FAILED","REFUNDED");case "REFUNDED"->List.of("PAID","FAILED");default->List.of("FAILED");};long eventCount=events.count(),grantCount=grants.count();var baseline=readOrder("PAY-020",id);String attempt=attempts.findByOrderId(id).orElseThrow().getStatus().name();for(String target:targets){simulate("PAY-020",id,target,409);assertEquals(baseline,readOrder("PAY-020",id));assertEquals(attempt,attempts.findByOrderId(id).orElseThrow().getStatus().name());assertEquals(eventCount,events.count());assertEquals(grantCount,grants.count());access("PAY-020",p,start.equals("PAID"));}}}
 @Test void pay021ExpireViaReadAndKeyReuse()throws Exception{for(boolean readFirst:List.of(true,false)){Product p=paid();String key="expiry-"+readFirst;JsonNode original=checkout("PAY-021","pending-"+readFirst,buyer,List.of(p.getId()),key,201);UUID id=orderId(original);overdue(id);assertEquals("PENDING",orders.findById(id).orElseThrow().getStatus().name());if(readFirst)assertEquals("EXPIRED",readOrder("PAY-021",id).path("status").asText());JsonNode replay=checkout("PAY-021","replay-"+readFirst,buyer,List.of(p.getId()),key,201);assertEquals(id,orderId(replay));assertEquals("EXPIRED",replay.path("status").asText());assertEquals(original.path("items"),replay.path("items"));assertEquals("EXPIRED",attempts.findByOrderId(id).orElseThrow().getStatus().name());assertEquals("EXPIRED",readOrder("PAY-021",id).path("status").asText());assertEquals(0,grants.count());assertEquals(0,events.count());}assertEquals(2,orders.count());assertEquals(2,attempts.count());}
