  UUID single=pricedOrder("snapshot-single","3.00",fixed.minusSeconds(60),fixed.minusSeconds(120),"PAID");JsonNode d=read("SALES-006","single-compat-snapshot","/api/creator/orders/"+single,owner,200);assertEquals(d.path("items").get(0).path("product"),d.path("product"));assertEquals(d.path("items").get(0).path("access"),d.path("access"));assertEquals(3,orders.count());
