  }

  &.disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  input[type='checkbox'] {
    display: none;
  }

  // Custom radio circle
  .checkbox-box {
    width: 18px;
    height: 18px;
    border-radius: 3px;
    border: 2px solid var(--text-secondary);
    position: relative;
    flex-shrink: 0;
    transition:
      border-color 0.2s ease,
      box-shadow 0.2s ease;
  }

  // When checked
  &.checked .checkbox-box {
    border-color: var(--brand-primary);
    box-shadow: 0 0 10px rgba(var(--brand-primary), 0.5);

    &::after {
      content: '✓';
      position: absolute;
      top: -6px;
      left: 2px;
      color: var(--brand-primary);
    }
  }

  .checkbox-label {
    font-size: 14px;
    color: var(--text-primary);
    font-weight: 500;
  }
}
